let type = ''
if (key.startsWith('n') || key.startsWith('N')) {
  type = 'novel'
  key = key.slice(1)
} else if (key.startsWith('c') || key.startsWith('C')) {
  type = 'comic'
  key = key.slice(1)
} else if (key.startsWith('a') || key.startsWith('A')) {
  type = 'audio'
  key = key.slice(1)
} else if (key.startsWith('v') || key.startsWith('V')) {
  type = 'video'
  key = key.slice(1)
} else {
  let typeZH = String(source.get('type')) || '小说'
  type = ['小说', '听小说', '出版', '短篇'].includes(typeZH) ? 'novel' : typeZH == '听书' ? 'audio' : typeZH == '漫画' ? 'comic' : 'video'
}
getApiUrl(`/${type}/search`, { keyword: key, page })

