ruleToc.chapterList:
@js:
let novelId = java.hexDecodeToString(result)
let type = JSON.parse(baseUrl.slice(baseUrl.indexOf('{'))).type
let typeZH = String(source.get('type')) || '小说'
if (type == 'novel' && typeZH == '听小说') {
  type = 'audio'
}

if (type == 'comic') {
  book.type = 64
} else if (type == 'audio') {
  book.type = 32
} else {
  book.type = 8
}

const loginInfo = JSON.parse(source.getLoginInfo() || '{}')
loginInfo.书籍ID = novelId
source.putLoginInfo(JSON.stringify(loginInfo))

result = requestApiUrl(`/${type}/catalog`, { novelId })
//java.log('result:' + JSON.stringify(result))

let cache = requestApiUrl(`/${type}/cache`, { novelId }) || []
cache = cache.reduce((acc, d) => {
  acc[d.chapId] = d
  return acc
}, {})

function formatCatalog(catalog) {
  catalog.forEach((c, index) => {
    let cacheChap = cache[c.item_id]
    let isShare = !!cacheChap
    let tag = isShare ? '🍅' : ''
    let onlineTime = c.first_pass_time
    let info = onlineTime
    if (type == 'novel') {
      info = `${onlineTime} ┃ 字数：${c.chapter_word_number || '-'}`
    } else if (type == 'comic') {
      info = `${onlineTime}${cacheChap ? ` ┃ 图片数：${cacheChap.imageCount || 0}` : ''}`
    }
    chaps.push({
      title: tag + c.title,
      info,
      url: `data:;base64,${java.base64Encode(c.item_id)},{"type":"${type}","novelId":"${novelId}","index":${index}}`,
    })
  })
}

let chaps = []
if (type == 'novel') {
  result.forEach(v => {
    chaps.push({
      title: v.volume,
      voltype: true
    })
    formatCatalog(v.chapters)
  })
} else {
  formatCatalog(result)
}
//java.log('chaps:' + JSON.stringify(chaps))
chaps

