try {
  let cinfo = src.replaceAll(" ", "").match(/createSvg2?\('(\d+)','(-?\d+)',(-?\d+),\d+,\d+\)/)
  let cacheKey = `fq-${cinfo[1]}-${cinfo[2]}-${cinfo[3]}`
  cache.deleteMemory(cacheKey)
} catch (err) {
  java.log(src + "-" + "Error:" + err)
}
