ruleBookInfo.init:
@js:
let novelId = java.hexDecodeToString(result)
let type = JSON.parse(baseUrl.slice(baseUrl.indexOf('{'))).type
let data = requestApiUrl(`/${type}/info`, { novelId })
if (data.category_schema) {
  let m = data.category_schema.match(/(genre_type|genreType)=(\d+)/)
  let genre_type = m ? m[2] : null
  if (genre_type == '0') {
    //type = 'novel'
  } else if (genre_type == '1') {
    type = 'audio'
  } else if (genre_type == '110') {
    type = 'comic'
  } else if (genre_type == '130') {
    type = 'video'
  }
}
data.type = type || 'novel'

let typeZH = String(source.get('type')) || '小说'
if (data.tones && (type == 'audio' || (type == 'novel' && typeZH == '听小说'))) {
  let tone = String(source.get('tone'))
  if (tone && !data.tones.split(',').includes(tone)) {
    java.longToast(`当前小说无音色：${tone}，将使用默认音色`)
  }
}
JSON.stringify(data)

