let api = 'https://fq.vv9v.cn'

function getApiUrl(path, data = {}) {
  let { source } = this
  data = Object.entries(data).map(v => v.join('=')).join('&')
  let androidId = String(source.get('androidId'))
  if (!androidId) {
    androidId = this.java.androidId()
    source.put('androidId', androidId)
  }
  let option = {
    method: "GET", headers: {
      'x-sec-token': source.getVariable(),
      'x-android-id': androidId
    }
  }
  let url = api + path + '?' + data + ',' + JSON.stringify(option)
  return url
}

function requestApiUrl(path, data) {
  let url = getApiUrl.call(this, path, data)
  try {
    let res = this.java.ajax(url)
    res = JSON.parse(res)
    if (res.error) {
      this.java.longToast(`\n操作失败，code${res.code}：\n${res.error}`)
    }
    if (res.data) {
      return res.data
    }
  } catch (e) {
    this.java.log(`请求共享接口${path}异常：` + e.message)
  }
  return null
}

function getComments(content, bid, cid, cIndex) {
  content = String(content)
  let isPC = this.source.get("段评") == '1'
  let isCC = this.source.get("章评") == '1'
  let isNC = this.source.get("书评") == '1'
  if (!bid || !cid || (!isPC && !isCC && !isNC)) {
    return content
  }
  let lines = content.split('\n')
  try {
    // 段评
    isPC && dealParagraphComment.call(this, lines, bid, cid)
    // 章评
    isCC && dealChapterComment.call(this, lines, bid, cid)
    // 书评
    cIndex == 0 && isNC && dealNovelComment.call(this, lines, bid)
    return lines.join("\n")
  } catch (err) {
    this.java.log(err)
    return content
  }
}

/** 处理段评 */
function dealParagraphComment(lines, bid, cid) {
  /** @type {import('../../src/api/Interface.ts').Novel.CommentParagraphInfo} */
  let data = requestApiUrl.call(this, '/novel/comment/paragraph_info', { bid, cid })
  if (!data) return
  let paragraphIds = Object.keys(data).map(Number)
  if (!paragraphIds.length) return
  // 拼接svg图
  let offset = 0
  paragraphIds.forEach(pid => {
    // this.java.log(`处理段落ID：${pid}，当前偏移量：${offset}`)
    let pIndex = pid + offset
    let pData = data[pid]
    if (lines[pIndex]) {
      while (/<img\s+[^>]*?src="[^"]+"[^>]*>/.test(lines[pIndex])) {
        offset += 1
        pIndex += 1
      }
      if (lines[pIndex] == '') return
      lines[pIndex] += `<img src="data:image/svg+xml;base64,,{"style":"TEXT","type":"fqpl","click":"createSvg('${bid}','${cid}',${pid},${pData.count},${Packages.java.lang.System.nanoTime()})","js":"createSvg('${bid}','${cid}',${pid},${pData.count},${Packages.java.lang.System.nanoTime()})"}">`
      let cacheKey = `fq-${bid}-${cid}-${pid}`
      this.cache.putMemory(cacheKey, '1')
    }
  })
}

